const source = $input.first().json;

const clean = (value) => String(value ?? '').trim();
const topic = clean(source.topic);
const audience = clean(source.audience) || 'general social media viewers';
const platform = clean(source.platform) || 'Instagram Reels';
const tone = clean(source.tone) || 'clear, engaging, and trustworthy';
const language = clean(source.language) || 'English';
const objective = clean(source.objective) || 'educate and retain attention';
const callToAction = clean(source.callToAction) || 'Follow for the next story';
const maxTopicLength = Number(source.maxTopicLength) || 240;

const errors = [];
if (!topic) {
  errors.push('topic is required');
}
if (topic.length > maxTopicLength) {
  errors.push(`topic must be ${maxTopicLength} characters or fewer`);
}

const durationMatch = clean(source.duration).match(/\d+/);
const requestedSeconds = durationMatch ? Number(durationMatch[0]) : 60;
const durationSeconds = requestedSeconds <= 45 ? 30 : 60;

const exampleRequest = {
  topic: 'How the Library of Alexandria disappeared',
  audience: 'history-curious adults',
  platform: 'Instagram Reels',
  duration: '60 seconds',
  tone: 'cinematic and factual',
  language: 'English',
  objective: 'educate and retain attention',
  callToAction: 'Follow for more hidden history',
};

if (errors.length > 0) {
  return [{
    json: {
      ok: false,
      statusCode: 400,
      error: 'Invalid video brief request',
      errors,
      exampleRequest,
      website: source.creatorUrl,
    },
  }];
}

const structure = durationSeconds === 30
  ? [
      { timing: '0-3s', purpose: 'Open with a specific curiosity gap or surprising claim.' },
      { timing: '3-10s', purpose: 'Establish the essential context without a long introduction.' },
      { timing: '10-24s', purpose: 'Deliver two or three escalating story beats with a new visual for each beat.' },
      { timing: '24-30s', purpose: 'Resolve the promise and deliver the call to action.' },
    ]
  : [
      { timing: '0-3s', purpose: 'Open with a specific curiosity gap or surprising claim.' },
      { timing: '3-15s', purpose: 'Establish the setting, stakes, and reason to keep watching.' },
      { timing: '15-45s', purpose: 'Develop three to five connected beats with clear visual progression.' },
      { timing: '45-56s', purpose: 'Deliver the payoff, lesson, or final reveal.' },
      { timing: '56-60s', purpose: 'Close with a concise, relevant call to action.' },
    ];

const recommendedSceneCount = durationSeconds === 30 ? '4-8 scenes' : '8-12 scenes';
const productionConstraints = [
  'Use a 9:16 vertical composition and keep the main subject clear on a phone screen.',
  'Write narration for natural spoken delivery; do not pad the script to hit an exact word count.',
  'Make every scene prompt visually distinct while preserving recurring character and style details.',
  'Keep on-screen captions short and synchronized to the spoken idea.',
  'Avoid unverifiable claims, copyrighted characters, and unsafe or misleading content.',
];

const copyReadyPrompt = [
  `Create a ${durationSeconds}-second faceless vertical video about: ${topic}.`,
  `Audience: ${audience}.`,
  `Platform: ${platform}.`,
  `Language: ${language}.`,
  `Tone: ${tone}.`,
  `Primary objective: ${objective}.`,
  `End with this call to action: ${callToAction}.`,
  `Plan ${recommendedSceneCount}. Start with a strong 0-3 second hook, build a connected story, and end with a clear payoff.`,
  'For each scene, provide narration, a specific visual prompt, and the intended caption phrase. Keep facts supportable and maintain visual continuity.',
].join('\n');

return [{
  json: {
    ok: true,
    statusCode: 200,
    requestId: `${Date.now()}-${Math.random().toString(36).slice(2, 10)}`,
    generatedAt: new Date().toISOString(),
    brief: {
      topic,
      audience,
      platform,
      duration: `${durationSeconds} seconds`,
      tone,
      language,
      objective,
      callToAction,
      recommendedSceneCount,
      structure,
      productionConstraints,
      copyReadyPrompt,
    },
    nextStep: {
      description: 'Paste copyReadyPrompt into Faceless Reels, then review the script and storyboard before production.',
      website: source.creatorUrl,
      createVideoUrl: source.createVideoUrl,
    },
  },
}];
